import re
from collections import OrderedDict

import json

from taf.internal.scf.exceptions import ElementNotFound
from taf.internal.scf.scf import SCF as InternalSCF
from taf.internal.scf.p import P
from taf.internal.scf.list import List
from taf.internal.scf.item import Item
from taf.internal.scf.managed_object import ManagedObject

import logging

from .exceptions import (
    MultipleMatches,
    ModificationStringException,
    AddItemParameterException,
    MatchNotFound,
)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SCFOperations(object):
    """ Provides keywords to perfmorm operattions on SCF file. Once loaded,
    parameters can be edited by calling `modify_scf_element` multiple times.
    After performing all operations file can be overwritten or
    new instance can be created using `save_scf` keyword.
    """
    managed_obj_tag = 'distName'
    namespaces = {'ns': 'raml21.xsd'}
    tags = {'element': 'p',
            'item': 'item',
            'list': 'list',
            'object': 'managedObject'}

    def __init__(self):
        self._internal_scf = None

    def load_scf(self, file_path):
        """" Load .xml file known as Site Configuration File.
        Data will be stored in volatile memory, loaded file will not be edited
        until `save_scf` keyword call.

        :param file_path: path as string
        """
        logger.debug('Loading SCF file: \'{}\''.format(file_path))
        self._internal_scf = InternalSCF(file_path)
        logger.debug('SCF parsed correctly')

    def save_scf(self, file_path, xml_declaration=True, encoding='UTF-8',
                 standalone=True):
        """ Save all changes, if another path than one during load operation
        given then new file will be created, old one remains without changes.

        :param file_path: path as string
        :param xml_declaration: default: True
        :param encoding: default: 'UTF-8'
        :param standalone: default: True
        """
        logger.debug('Saving edited SCF to \'{}\''.format(file_path))
        self._internal_scf.save(file_path, xml_declaration, encoding, standalone)
        logger.debug('SCF saved correctly')

    def get_value_from_scf(self, **kwargs):
        """ Reads single value of p element. If there is no direct way to point at specific
        element (some of them are not named properly or there are duplicated names),
        and one can avoid exception if multiple matches found, index attribute can be used to
        return specific element from list of matches. For values of managed object's attributes
        keyword 'get_mo_attribute' should be used.


        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
                          None is default value.
        :param p_name: 'name' attribute in <p> tag, None is default value
        :param list_name: 'name' attribute in <list> tag, None is default value
        :param index: optional parameter, should be castable to int (int or str). Should be
                      used if more than one match expected. Indexing starts from 0.
        :return: read value as string.
        :raises KeyError if no elements found
        :raises MultipleMatches if more than one element found and index is not given
        :raises IndexError if given index is bigger or equal to number of matches
        """
        el = self._get_one_element(**kwargs)
        if el is not None:
            return el.value_as_text

    def get_all_values_from_scf(self, **kwargs):
        """  Returns list of all matched values of p elements, does expect any specific
        number of matches. For values of managed object's attributes keyword 'get_mo_attribute'
        should be used.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
                          None is default value.
        :param p_name: 'name' attribute in <p> tag, None is default value
        :param list_name: 'name' attribute in <list> tag, None is default value
        :return: read value as string.
        """
        return [el.value_as_text for el in self._get_all_elements(**kwargs)]

    def get_all_values_from_scf_by_pattern(self, **kwargs):
        """ Same as `get_all_values_from_scf` but expects regular expressions\
        in dist_name, p_name or list_name.
        """
        return [el.value_as_text for el in self._get_all_elements_by_pattern(**kwargs)]

    def get_all_dist_names_of_specific_class(self, mo_class):
        """  Returns list of all dist names that match specific class, does expect specific
        class name from managed object.

        :param mo_class: in <managedObject> as 'class', e.g.: 'com.nokia.sbts:RAP'
        :return: list of dist names values that match provided class
        """
        matched_managed_objects = self._internal_scf.raml.cmData.get_dist_names_by_class(mo_class)
        logger.debug(f"Used XPath: {matched_managed_objects.used_xpath}")
        logger.debug(f'Found {len(matched_managed_objects)} matches')
        return [el.dist_name for el in matched_managed_objects]

    def get_all_dist_names_by_pattern(self, pattern):
        """  Returns list of all dist names that match regex pattern, does expect regex.

        :param pattern: regular expression, e.g.: 'RMOD*'
        :return: list of dist names values that match regex pattern
        """
        matched_managed__objects = self._internal_scf.raml.cmData.get_dist_names_by_pattern(pattern)
        logger.debug(f"Used XPath: {matched_managed__objects.used_xpath}")
        logger.debug(f"Found {len(matched_managed__objects)} matches")
        return [el.dist_name for el in matched_managed__objects]

    def modify_scf_element(self, value, **kwargs):
        """ Reads single value. Attributes are mapped to SCF element's attributes.
        If there is not direct way to point at specific element (some of them
        are not named properly or there are duplicated names), and one can avoid
        exception if multiple matches found, index attribute can be used to
        modify specific element from list of matches.

        :param value: new value
        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
                          None is default value.
        :param p_name: 'name' attribute in <p> tag, None is default value
        :param list_name: 'name' attribute in <list> tag, None is default value
        :param index: optional parameter, should be castable to int (int or str). Should be
                      used if more than one match expected. Indexing starts from 0.
        :raises KeyError if no elements found
        :raises MultipleMatches if more than one element found and index is not given
        :raises IndexError if given index is bigger or equal to number of matches
        """
        el = self._get_one_element(**kwargs)
        el.value = value
        logging_message = 'Modified value of node with attributes "{}" to value="{}"'
        logging_message = logging_message.format(kwargs, value)
        self._log_scf_modification(logging_message)

    def _get_one_element(self, dist_name=None, list_name=None, p_name=None, index=None):
        matched_elements = self._get_all_elements(dist_name, list_name, p_name)
        number_of_matches = len(matched_elements)
        if number_of_matches == 0:
            raise KeyError(f"No match found! Query might be not valid. "
                           f"Used XPath: {matched_elements.used_xpath}")
        elif number_of_matches > 1 and index is None:
            raise MultipleMatches(number_of_matches, matched_elements.used_xpath)
        else:
            logger.debug(f"Used XPath: {matched_elements.used_xpath}")
            index = int(index) if index is not None else 0
            if index >= number_of_matches:
                raise IndexError(f"Given index {index} is out of range. "
                                 f"Number of found matches: {number_of_matches}")
            return matched_elements[index]

    def _get_all_elements(self, dist_name=None, list_name=None, p_name=None):
        if dist_name == '':
            dist_name = None
        if list_name == '':
            list_name = None
        if p_name == '':
            p_name = None

        matched_elements = self._internal_scf.raml.cmData.get_all_elements(dist_name, list_name, p_name)
        logger.debug(f"Used XPath: {matched_elements.used_xpath}")
        logger.debug(f"Found {len(matched_elements)} matches")
        return matched_elements

    def _get_all_elements_by_pattern(self, dist_name=None, list_name=None, p_name=None):
        if dist_name == '':
            dist_name = None
        if list_name == '':
            list_name = None
        if p_name == '':
            p_name = None

        matched_elements = self._internal_scf.raml.cmData.get_all_elements_by_pattern(dist_name, list_name, p_name)
        logger.debug(f"Used XPath: {matched_elements.used_xpath}")
        logger.debug(f"Found {len(matched_elements)} matches")
        return matched_elements

    def _extract_gnb_version(self):
        cmData = self._internal_scf.raml.cmData
        if len(cmData) > 0:
            return cmData[0].dist_name

    def remove_block_from_scf(self, dist_name=None, list_name=None,
                              p_name=None, index=None):
        """ Removes element from loaded SCF. Attributes are mapped to SCF element's
        attributes. If p_name or index given it removes only single element. If not
        the whole managedObject is removed. Changes are saved only after save_scf
        keyword.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
                          None is default value.
        :param list_name: 'name' attribute in <list> tag, None is default value
        :param p_name: 'name' attribute in <p> tag, None is default value. If not given and
                       param index not given the whole managedObject is removed
        :param index: int or str, optional parameter, should be castable to int. Should be
                      used if more than one match expected. Indexing starts from 0. If not
                      given and param p_name not given the whole managedObject is removed.
        """
        if list_name is None and p_name is None and index is None:
            self._get_node(dist_name).remove()
        else:
            elem = self._get_one_element(dist_name, list_name, p_name, index)
            elem.remove()
        attributes = {'dist_name': dist_name, 'list_name': list_name,
                      'p_name': p_name, 'index': index}
        logging_message = 'Removed node with attributes: {}'
        self._log_scf_modification(logging_message.format(attributes))

    def remove_list_from_scf(self, dist_name, list_name):
        """ Removes list from loaded SCF inside managed object indicated in 'dist_name'.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param str list_name: 'name' attribute in <list> tag
        :raise ElementNotFound: when 'dist_name' not found inside given SCF
        """
        self._get_node(dist_name=dist_name, child_name=list_name).remove()

    def add_element_to_scf(self, dist_name, p_name, value):
        """ Adds element to object in loaded SCF. The object is mapped by the attribute
        distName. The element is added at the end of list of objects children.
        Changes are saved only after save_scf keyword.

        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param p_name: name of attribute of new element
        :param value: value of new element

        """
        p_elem = P().create(value=value, name=p_name, ns=self._internal_scf.raml.xmlns)
        self._get_node(dist_name).append(p_elem)

        logging_message = 'Added element with p_name="{}" and value="{}" to object with dist_name="{}".'
        logging_message = logging_message.format(p_name, value, dist_name)
        self._log_scf_modification(logging_message)

    def add_list_to_scf(self, dist_name, list_name):
        elem = List().create(name=list_name, ns=self._internal_scf.raml.xmlns)
        self._get_node(dist_name).append(elem)

        logging_message = 'Added list {} to scf'.format(list_name)
        self._log_scf_modification(logging_message)

    def add_item_to_list(self, dist_name, list_name, elements):
        parent = getattr(self._get_node(dist_name), list_name)
        new_item = Item().create(ns=self._internal_scf.raml.xmlns)
        for p_name, value in elements.items():
            elem = P().create(value=value, name=p_name, ns=self._internal_scf.raml.xmlns)
            new_item.append(elem)
            logging_message = 'Added element with p_name={} and value={} ' \
                              'to item in list "{}" in object of dist_name={}'
            logging_message = logging_message.format(p_name, value, list_name, dist_name)
            self._log_scf_modification(logging_message)
        parent.append(new_item)

    def add_elements_to_list(self, dist_name, list_name, elements):
        parent = getattr(self._get_node(dist_name), list_name)
        for element in elements:
            elem = P().create(value=element, ns=self._internal_scf.raml.xmlns)
            parent.append(elem)
            logging_message = 'Added element "{}" to list "{}" in object of dist_name={}'
            logging_message = logging_message.format(element, list_name, dist_name)
            self._log_scf_modification(logging_message)

    def _get_node(self, dist_name=None, child_name=None):
        dist_name = self._create_node_path(dist_name)
        mos = self._internal_scf.raml.cmData.get_all_descendant_mos()
        for mo in mos:
            if mo.dist_name == dist_name:
                if not child_name:
                    return mo
                else:
                    node = getattr(mo, child_name)
                    return node

        raise ElementNotFound()

    def add_object_to_scf(self, class_name, dist_name, version, operation):
        """ Adds whole managedObject to loaded SCF. All parameters are mandatory and
        are addded as attributes to the object. Elements to the object can be added
        only after saving the SCF file and loading it again.

        :param class_name: added as attribute 'class'
        :param dist_name: in <managedObject> as 'distName', SBTS prefix can be ommited e.g.:
                          both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent.
        :param version: added as attribute 'version'
        :param operation: added as attribute 'operation', default value is 'create'
        """
        dist_name = self._create_node_path(dist_name)
        attributes = {'class': class_name, 'distName': dist_name,
                      'operation': operation, 'version': version}
        mo = ManagedObject().create(klass=class_name, dist_name=dist_name, version=version,
                                    operation=operation, ns=self._internal_scf.raml.xmlns)
        self._internal_scf.raml.cmData.append(mo)
        logging_message = 'Added managedObject with attributes: {}'.format(attributes)
        self._log_scf_modification(logging_message)

    @staticmethod
    def _log_scf_modification(message, level='INFO'):
        logging_message = '[SCF MODIFICATION] {}'.format(message)
        logger.debug(logging_message) if level == 'DEBUG' else logger.info(logging_message)

    def is_in_scf(self, dist_name, child_name=None):
        """ Checks whether loaded SCF contains given node.

        :param str dist_name: distName of checked object or parent node
        :param str child_name: name of child node - list_name or p_name; defaults to None - then object is checked
        :return: True if SCF contains given node, False otherwise
        :rtype: bool
        """
        try:
            self._get_node(dist_name, child_name)
            return True
        except ElementNotFound:
            return False

    def _create_node_path(self, dist_name, child_name=None):
        """ Creates path to SCF node by transforming and combining distName and it's child name.
        :param str dist_name: name of (parent) object
        :param str child_name: name of child node
        :return: path to SCF node
        :rtype: str
        """
        path_root = self._extract_gnb_version()
        if path_root is not None and path_root not in dist_name:
            dist_name = path_root + '/' + dist_name

        if child_name is None:
            return dist_name if not dist_name.endswith('/') else dist_name[:-1]
        else:
            child_path = "." + child_name if child_name else ""
            return dist_name.replace("/", ".").replace("-", "_") + child_path

    def clone_mo_with_descendant_mos(self, source_mo_dist_name, new_dist_name):
        source_node = self._get_node(source_mo_dist_name)
        new_dist_name = self._create_node_path(dist_name=new_dist_name)
        source_node.clone_tree_to(new_dist_name)

    def remove_mo_with_descendant_mos(self, dist_name):
        """ Removes managed object with given distName together with all its descendant managed objects.
        I.e. 'SBTS-1900/TNL-4/ETHSVC-1' will be removed together with its descendants:
        'SBTS-1900/TNL-4/ETHSVC-1/ETHIF-1' and 'SBTS-1900/TNL-4/ETHSVC-1/ETHLK-1'.

        :param str dist_name: distName of parent managed object which will be removed
        :except ElementNotFound: raised when parent managed object is not found in loaded SCF
        """
        self._get_node(dist_name).remove_tree()

    def get_mo_attribute(self, dist_name, attribute):
        """ Returns value of parameter 'attribute' of managed object indicated in 'dist_name'.
        Example:
        Data: <managedObject distName="SBTS-1900/RAP-1" version="5G17_1707_001">
        Function call: get_mo_attribute("SBTS-1900/RAP-1", "version")
        Return value: "5G17_1707_001"

        :param str dist_name: distName of managed object
        :param str attribute: attribute name of indicated managed object

        :raises KeyError: when managed object named 'dist_name' does not have proper attribute

        :rtype: str
        :return: value of 'attribute'
        """
        return self._get_node(dist_name)[attribute]

    def set_mo_attribute(self, dist_name, attribute, value):
        """ Sets parameter 'attribute' of managed object indicated in 'dist_name' to 'value'.
        Example:
        Data: <managedObject distName="SBTS-1900/RAP-1" version="5G17_1707_001">
        Function call: set_mo_attribute("SBTS-1900/RAP-1", "version", "new_version")
        Updated data: <managedObject distName="SBTS-1900/RAP-1" version="new_version">
        Return value: "new_version"

        :param str dist_name: distName of managed object to be updated
        :param str attribute: attribute to be changed (or set if attribute doesn't exist in indicated managed object)
        :param str value: new value of 'attribute'

        :raises KeyError: when 'attribute' is invalid within the context of raml21.xsd. List of valid
                          attributes: class, version, operation, distName, id, name, vendor, timeStamp
        """
        valid_attribs = ['class', 'version', 'operation', 'distName', 'id', 'name', 'vendor', 'timeStamp']
        if attribute not in valid_attribs:
            raise KeyError("Invalid attribute {0}".format(attribute))
        self._log_scf_modification("Setting {0} of {1} to {2}".format(attribute, dist_name, value))

        mo = self._get_node(dist_name)
        mo[attribute] = value

    def delete_mo_attribute(self, dist_name, attribute):
        """ Delete parameter 'attribute' of managed object indicated by 'dist_name'.
        Example:
        Data: <managedObject distName="SBTS-1900/RAP-1" version="5G17_1707_001">
        Function call: delete_mo_attribute("SBTS-1900/RAP-1", "version")
        Updated data: <managedObject distName="SBTS-1900/RAP-1">

        :param str dist_name: distName of managed object to be updated
        :param str attribute: attribute to be deleted

        :raises KeyError: when 'attribute' is invalid within the context of raml21.xsd. List of valid
                          attributes: class, version, operation, distName, id, name, vendor, timeStamp
        """
        valid_attribs = ['class', 'version', 'operation', 'distName', 'id', 'name', 'vendor', 'timeStamp']
        if attribute not in valid_attribs:
            raise KeyError(f"Invalid attribute {attribute}")
        self._log_scf_modification(f"Deleting {attribute} of {dist_name}")

        mo = self._get_node(dist_name)
        if attribute in mo._tree.attrib:
            del mo._tree.attrib[attribute]

    def perform_scf_modification(self, modification_strings):
        """
        Perform SCF modifications.

        There are 3 possible operations: ``add``, ``delete``, and ``modify``. Each
        of them has different possibilities, please refer to the below explanation. Multiple operations can be added at
        the same time via string entries in ``params_in_scf`` list.

        Modifications are performed based on provided ManagedObject name(s), for example:

        if ManagedObject has distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1", then RTPOL-1 is used;
        if there are more matches for the same mo_name, e.g:
           distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
           distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0",
        then ``mo_name`` will be the last two elements combined together -> mo_name = LNCEL-27251/SIB-0, etc.

        Since a greedy search is performed for provided MO names, multiple matches are possible. For example, if
        MRBTS-2725/WNBTS-1/WNCEL-1 is used in a modification string, objects such as MRBTS-2725/WNBTS-1/WNCEL-11
        or MRBTS-2725/WNBTS-1/WNCEL-13 are considered matches and will be modified as well.
        To avoid that, please put a $ sign at the end of distName: MRBTS-2725/WNBTS-1/WNCEL-1$.

        :param list(str) modification_strings: it consist of modification strings, please refer to the below
                         explanation.


        EXAMPLES FOR ADD OPERATION
        - add parameter to list with condition_key
        (add srcIpPrefixLength parameter with value 27 to routingPolicies <list> element where orderNumber=1):
        'add:RTPOL-1:routingPolicies:srcIpPrefixLength=27|orderNumber=1'

        - add parameter to list element
        (add srcIpAddress parameter with value 0.0.0.0 to <list>; if <list> consists of multiple <item>s,
        then this operation will affect all of them):
        'add:RTPOL-1:routingPolicies:srcIpAddress=0.0.0.0'

        - add parameter to list
        (add param with value 4, i.e. <p>4</p>, to wncelIdList under WNCELG-1)
        'add:WNCELG-1:wncelIdList::4'

        - add item to list
        (add item with "param_name": "value" entries, e.g., example: add <item> to routingPolicies <list> with entry
        "orderNumber": "5"):
        'add:RTPOL-1:routingPolicies:{"orderNumber": "5"}'

        - add parameter to ManagedObject
        (add shareOfHSDPAUser=100 to WNCELG-1):
        'add:WNCELG-1:shareOfHSDPAUser=100'

        - add list to ManagedObject
        (add cPlaneList <list> element to WNBTS-1)
        'add:WNBTS-1:cPlaneList'

        - add ManagedObject to SCF
        (add second group WNCELG-2 to SCF.
        In square brackets there are 4 groups:
            - class_name
            - dist_name
            - version
            - operation)
        'add:[com.nokia.srbts.wcdma:WNCELG, MRBTS-2725/WNBTS-1/WNCELG-2, WCDMA18_1711_005, create]'

        EXAMPLES FOR MODIFY OPERATION
        - modify list parameter with condition_key
        (modify srcIpPrefixLength parameter, i.e., set it to value 24 in routingPolicies <list> element where
        orderNumber=1)
        'modify:RTPOL-1:routingPolicies:srcIpPrefixLength=24|orderNumber=1'

        - modify list parameter
        (modify srcIpAddress parameter, i.e., set it to value 1.1.1.1 in routingPolicies <list>; if <list> consists of
        multilpe <item>s, then this operation will affect all of them)
        'modify:RTPOL-1:routingPolicies:srcIpAddress=1.1.1.1'

        - modify list by creating a new list with provided values
        (modify wncelIdList with new values 1,2,3, or in fact, <p>1</p><p>2</p><p>3</p>)
        'modify:WNCELG-1:wncelIdList=1,2,3'

        - modify list by creating a new list with one value
        (modify wncelIdList with new values 1, or in fact, <p>1</p>)
        'modify:WNCELG-1:wncelIdList=1,'

        - modify param in ManagedObject
        (modify aldScanningInterval under APEQM-1 to value 'enabled')
        'modify:APEQM-1:aldScanningInterval=enabled'


        EXAMPLES FOR DELETE OPERATION
        - delete whole list item with condition_key
        (delete staticRoutes <item> under IPRT-1 where destinationIpPrefixLength is 24)
        'delete:IPRT-1:staticRoutes:{}|destinationIpPrefixLength=24'

        - delete a single parameter on list with condition key
        (delete destIpAddr parameter under IPRT-1/staticRoutes where destinationIpPrefixLength is 24)
        'delete:IPRT-1:staticRoutes:destIpAddr|destinationIpPrefixLength=24'

        - delete list parameter which is not located under any <item> element
        (delete test_parameter located in routingPolicies <list> under RTPOL-1 which is not under any <item> element)
        'delete:RTPOL-1:routingPolicies:test_parameter'

        - delete element (list or parameter) in given ManagedObject
        (delete parameter accessBbCapacity under WNCELG-1)
        'delete:WNCELG-1:accessBbCapacity'

        (delete list wncelIdList under WNCELG-1)
        'delete:WNCELG-1:wncelIdList'

        - delete ManagedObject
        (delete whole ManagedObject WNCELG-1)
        'delete:WNCELG-1'
        """

        modifications = OrderedDict()

        modifications['add_list_param_with_condition_key_regex'] = [
            re.compile(r'(?P<operation>add):(?P<mo_name>.+):(?P<list_name>.+):'
                       r'(?P<p_name>.+)=(?P<value>.+)\|(?P<condition_key>.+)'
                       r'=(?P<condition_value>.+)'),
            self.perform_operation_on_list_parameter
        ]

        modifications['add_list_item_param_regex'] = [
            re.compile(r'(add):(?P<mo_name>.+):(?P<list_name>.+):(?P<p_name>.+)='
                       r'(?P<value>.+)'),
            self.add_scf_parameter_inside_item_by_mo
        ]

        modifications['add_items_to_list_regex'] = [
            re.compile(r'(add):(?P<mo_name>.+):(?P<list_name>.+):(?P<elements>{.+})'),
            self.add_item_to_list_by_mo
        ]

        modifications['add_list_param_regex'] = [
            re.compile(r'(add):(?P<mo_name>.+):(?P<list_name>.+):(?P<p_name>.+)?:'
                       r'(?P<value>.+)'),
            self.add_scf_parameter_inside_list_by_mo
        ]

        modifications['add_param_to_mo_regex'] = [
            re.compile(r'(add):(?P<mo_name>.+):(?P<p_name>.+)=(?P<value>.+)'),
            self.add_scf_parameter_inside_mo_by_mo
        ]

        modifications['add_MO_regex'] = [
            re.compile(r'(add):\[(?P<mo_desc>.+)\]'),
            self.add_MO_to_scf
        ]

        modifications['add_list_regex'] = [
            re.compile(r'(add):(?P<mo_name>.+):(?P<list_name>.+)'),
            self.add_list_by_mo
        ]

        modifications['modify_list_param_with_condition_key_regex'] = [
            re.compile(r'(?P<operation>modify):(?P<mo_name>.+):'
                       r'(?P<list_name>.+):(?P<p_name>.+)=(?P<value>.+)\|'
                       r'(?P<condition_key>.+)='
                       r'(?P<condition_value>.+)'),
            self.perform_operation_on_list_parameter
        ]

        modifications['modify_list_param_regex'] = [
            re.compile(r'(modify):(?P<mo_name>.+):(?P<list_name>.+):(?P<p_name>.+)='
                       r'(?P<value>.+)'),
            self.modify_scf_element_by_mo
        ]

        modifications['modify_list_values_to_list_regex'] = [
            re.compile(r'(modify):(?P<mo_name>.+):(?P<list_name>.+)='
                       r'(?P<values_list>.+,.*)'),
            self.modify_scf_list_with_list_of_values
        ]

        modifications['modify_param_regex'] = [
            re.compile(r'(modify):(?P<mo_name>.+):(?P<p_name>.+)=(?P<value>.+)'),
            self.modify_scf_element_by_mo
        ]

        modifications['delete_list_item_with_condition_key_regex'] = [
            re.compile(r'(?P<operation>delete):(?P<mo_name>.+):(?P<list_name>'
                       r'.+):\{\}\|(?P<condition_key>.+)='
                       r'(?P<condition_value>.+)'),
            self.perform_operation_on_list_parameter
        ]

        modifications['delete_list_param_with_condition_key_regex'] = [
            re.compile(r'(?P<operation>delete):(?P<mo_name>.+):'
                       r'(?P<list_name>.+):(?P<p_name>.+)\|(?P<condition_key>'
                       r'.+)=(?P<condition_value>.+)'),
            self.perform_operation_on_list_parameter
        ]

        modifications['delete_list_param_regex'] = [
            re.compile(r'(delete):(?P<mo_name>.+):(?P<element_name>.+):(?P<p_name>.+)'),
            self.delete_block_from_scf_by_pattern
        ]

        modifications['delete_element_regex'] = [
            re.compile(r'(delete):(?P<mo_name>.+):(?P<element_name>.+)'),
            self.delete_block_from_scf_by_pattern
        ]

        modifications['delete_mo_regex'] = [
            re.compile(r'(delete):(?P<mo_name>.+)'),
            self.delete_block_from_scf_by_pattern
        ]

        at_least_one_match_not_found = None
        for ms in modification_strings:
            try:
                self._log_scf_modification('Start modification for: {}'.format(ms))
                self._perform_modification(ms, modifications)
            except MatchNotFound:
                at_least_one_match_not_found = True
                self._log_scf_modification('No match for: {}'.format(ms))
            finally:
                self._log_scf_modification('End modification for: {}'.format(ms))

        if at_least_one_match_not_found:
            raise MatchNotFound("At least one pattern not found. Check prior 'No match for' traces.")
        self._log_scf_modification('All SCF modifications successfully performed')

    def _perform_modification(self, ms, modifications):
        for name, (pattern, operation) in modifications.items():
            match = pattern.search(ms)
            if match:
                params = self._process_match(match)
                if name == 'delete_list_item_with_condition_key_regex':
                    params['operation'] = 'delete_item'
                self._log_scf_modification(f"Matched {name} pattern, "
                                           f"starting {operation.__name__} operation with parameters: {params}")
                operation(**params)
                break
        else:
            raise ModificationStringException("None of regexs matched modification parameter string "
                                              "from SCF PARAMS LIST\n There is an issue with input: "
                                              "{}'".format(ms))

    @staticmethod
    def _process_match(match):
        valid_params = ['operation', 'mo_name', 'list_name', 'p_name', 'value', 'elements', 'condition_key',
                        'condition_value', 'values_list', 'element_name', 'mo_desc']

        params_dict = {}
        for item in valid_params:
            try:
                params_dict.update({item: match.group(str(item))})
            except IndexError:
                pass
        return params_dict

    def modify_scf_element_by_mo(self, mo_name, list_name=None, p_name=None, value=None):
        """
        Modify value of matched parameters. Attributes are mapped to attributes of an SCF element.

        Raises ``KeyError`` exception if no matching elements are found. Changes are saved only after
        executing ``save_scf`` keyword.

        :param str mo_name: in <managedObject> 'distName' should be used to provide the last element after split operation
            ('/' is used as a separator), e.g.:
            distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1

            If there are more matches for the same ``mo_name``, for example:
            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0",
            then ``mo_name`` will be the last two elements combined together -> mo_name = LNCEL-27251/SIB-0, etc.
        :param str list_name: 'name' attribute in <list> tag, None is default value
        :param str p_name: 'name' attribute in <p> tag, None is default value
        :param str value: new value
        """
        matched_elements = self._get_elements_by_pattern(mo_name=mo_name, list_name=list_name, p_name=p_name)
        for element in matched_elements:
            self._log_scf_modification(f"Modify '{element.name}' value: {element.value} -> {value}")
            element.value = value
        attributes = {'mo_name': mo_name, 'list_name': list_name,
                      'p_name': p_name}
        logging_message = 'Modified value of node with attributes "{}" to value="{}"'
        logging_message = logging_message.format(attributes, value)
        self._log_scf_modification(logging_message)

    def _get_elements_by_pattern(self, mo_name=None, list_name=None, p_name=None):
        mo_name = mo_name or None
        list_name = list_name or None
        p_name = p_name or None

        matched_elements = self._search_elements_by_pattern(mo_name, list_name, p_name)

        if not matched_elements:
            logger.warning(f'[SCF MODIFICATION] No match for MO: {mo_name}, list: {list_name}, parameter: {p_name}')
            raise MatchNotFound("No match found! Query might be not valid.")

        return matched_elements

    def _search_elements_by_pattern(self, mo_name=None, list_name=None, p_name=None):
        self._log_scf_modification(
            message=f'Searching elements by pattern: mo_name={mo_name}, list_name={list_name}, p_name={p_name}',
            level='DEBUG')
        if not mo_name.startswith(('MRBTS', 'NRBTS')):  # if MO is main MRBTS or NRBTS object
            mo_name = "/" + mo_name                     # then distname doesnt start with /
        matched_elements = self._internal_scf.raml.cmData.get_all_elements_by_pattern(mo_name, list_name, p_name)
        self._log_scf_modification(message=f"Used XPath: {matched_elements.used_xpath}", level='DEBUG')
        self._log_scf_modification(message=f'Found {len(matched_elements)} matches', level='DEBUG')
        return matched_elements

    def add_scf_parameter_inside_item_by_mo(self, mo_name, list_name=None, p_name=None, value=None):
        """
        Add parameter inside list item object in loaded SCF.

        Changes are saved only after ``save_scf`` keyword is executed.
        If list contains multiple items, then parameter will be added to all of them.

        :param str mo_name: in <managedObject> 'distName' should be used to provide the last element after split
        operation ('/' is used as separator),
        e.g.: distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1
            If there are more matches for the same ``mo_name``, e.g:
            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0",
            then ``mo_name`` will be last two elements combined together -> mo_name = LNCEL-27251/SIB-0 etc.
        :param str list_name: 'name' attribute in <list> tag, None is default value
        :param str p_name: 'name' attribute in <p> tag, None is default value
        :param str value: new value
        """
        matched_element = self._get_node_by_mo(mo_name=mo_name, child_name=list_name)
        matched_items = [element for element in matched_element if not isinstance(element, P)]
        if matched_items:
            for item in matched_items:
                param_exists = any(p.name == p_name for p in item)
                if not param_exists:
                    p_elem = P().create(value=value, name=p_name, ns=self._internal_scf.raml.xmlns)
                    item.append(p_elem)
                else:
                    logger.warning('[SCF MODIFICATION] Parameter already exists, modifying value instead of adding new one')
                    self.modify_scf_element_by_mo(mo_name=mo_name, list_name=list_name, p_name=p_name, value=value)
        else:
            raise AddItemParameterException('List does not contain any items')
        attributes = {'mo_name': mo_name, 'list_name': list_name,
                      'p_name': p_name}
        logging_message = 'Added paramter to <item(s)> under path"{}" with value="{}"'
        logging_message = logging_message.format(attributes, value)
        self._log_scf_modification(logging_message)

    def add_scf_parameter_inside_list_by_mo(self, mo_name, list_name=None, p_name=None, value=None):
        """
        Add parameter inside list object in loaded SCF.

        Changes are saved only after ``save_scf`` keyword is executed.

        :param str mo_name: in <managedObject> 'distName' shall be used to provide last element after split operation
                            ('/' is used as separator) e.g.:
                            distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1

                            If there are more matches for the same mo_name e.g:
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0"
                            Then mo_name will be last two elements combined together -> mo_name = LNCEL-27251/SIB-0 etc.

        :param str list_name: 'name' attribute in <list> tag, None is default value
        :param str p_name: 'name' attribute in <p> tag, None is default value
        :param str value: new value
        """
        if self._get_all_elements(mo_name, list_name, p_name):
            logger.warning(f'[SCF MODIFICATION] Parameter "{p_name}" already exists, modifying its value to "{value}"!')
            self.modify_scf_element_by_mo(mo_name=mo_name, p_name=p_name, value=value)
        else:
            parent = getattr(self._get_node_by_mo(mo_name), list_name)
            p_elem = P().create(value=value, name=p_name, ns=self._internal_scf.raml.xmlns)
            parent.append(p_elem)
            attributes = {'mo_name': mo_name, 'list_name': list_name,
                          'p_name': p_name}
            logging_message = 'Added parameter to <list> under path "{}" with value="{}"'
            logging_message = logging_message.format(attributes, value)
            self._log_scf_modification(logging_message)

    def add_scf_parameter_inside_mo_by_mo(self, mo_name, p_name=None, value=None):
        """
        Add parameter inside object in loaded SCF.

        Changes are saved only after ``save_scf`` keyword is executed.

        :param str mo_name: in <managedObject> 'distName' shall be used to provide last element after split operation
                            ('/' is used as separator) e.g.:
                            distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1

                            If there are more matches for the same mo_name e.g:
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0"
                            Then mo_name will be last two elements combined together -> mo_name = LNCEL-27251/SIB-0 etc.

        :param str p_name: 'name' attribute in <p> tag, None is default value
        :param str value: new value
        """
        if self._search_elements_by_pattern(mo_name=mo_name, p_name=p_name):
            logger.warning(f'[SCF MODIFICATION] Parameter "{p_name}" already exists, modifying its value to "{value}"!')
            self.modify_scf_element_by_mo(mo_name=mo_name, p_name=p_name, value=value)
        else:
            p_elem = P().create(value=value, name=p_name, ns=self._internal_scf.raml.xmlns)
            self._get_node_by_mo(mo_name).append(p_elem)
            attributes = {'mo_name': mo_name, 'p_name': p_name}
            logging_message = 'Added paramter to <MO> under path"{}" with value="{}"'
            logging_message = logging_message.format(attributes, value)
            self._log_scf_modification(logging_message)

    def add_list_by_mo(self, mo_name, list_name):
        """
        This KW adds list to object in loaded SCF. Changes are saved only after save_scf keyword.

        :param str mo_name: in <managedObject> 'distName' shall be used to provide last element after split operation
                            ('/' is used as separator) e.g.:
                            distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1

                            If there are more matches for the same mo_name e.g:
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0"
                            Then mo_name will be last two elements combined together -> mo_name = LNCEL-27251/SIB-0 etc.
        :param str list_name: 'name' attribute in <list> tag, None is default value
        """
        elem = List().create(name=list_name, ns=self._internal_scf.raml.xmlns)
        self._get_node_by_mo(mo_name=mo_name).append(elem)
        logging_message = 'Added <list> to {} with name: "{}"'
        logging_message = logging_message.format(mo_name, list_name)
        self._log_scf_modification(logging_message)

    def add_item_to_list_by_mo(self, mo_name, list_name, elements):
        """
        This KW adds new item to list object in loaded SCF. Changes are saved only after save_scf keyword.

        :param str mo_name: in <managedObject> 'distName' shall be used to provide last element after split operation
                            ('/' is used as separator) e.g.:
                            distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1

                            If there are more matches for the same mo_name e.g:
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0"
                            Then mo_name will be last two elements combined together -> mo_name = LNCEL-27251/SIB-0 etc.
        :param str list_name: 'name' attribute in <list> tag, None is default value
        :param str elements: comma separated mapping in form of dictionary of new item elements.
                             Example: {"srcIpAddress": "0.0.0.0""} <- in method body json.loads() is called on str
                             elements
        """
        elements = json.loads(elements)
        parent = getattr(self._get_node_by_mo(mo_name), list_name)
        new_item = Item().create(ns=self._internal_scf.raml.xmlns)
        for p_name, value in elements.items():
            elem = P().create(value=value, name=p_name, ns=self._internal_scf.raml.xmlns)
            new_item.append(elem)
            logging_message = ('Added element with p_name={} and value={} '
                               'to item in list "{}" in object of dist_name={}')
            logging_message = logging_message.format(p_name, value, list_name, mo_name)
            self._log_scf_modification(logging_message)
        parent.append(new_item)

    def add_MO_to_scf(self, mo_desc):
        """
        Add managedObject to loaded SCF based on provided description ``mo_desc``.
        ManagedObject description consists of four values (comma separated): class_name, dist_name, version, and
        operation
        All four parameters are mandatory and are added as attributes to the object. Changes are saved only after
        ``save_scf`` keyword is executed.
        :param str mo_desc comma separated values:
            - class_name: added as <managedObject>'s 'class' attribute
            - dist_name: added as 'distName' attribute;
                SBTS prefix can be ommited, e.g., both 'SBTS-1900/NGNODEB-1' and 'NGNODE-1' are valid and equivalent
            - version: added as 'version' attribute
            - operation: added as 'operation' attribute
        """
        elements = mo_desc.replace(' ', '')
        class_name, dist_name, version, operation = elements.split(',')
        dist_name = self._create_node_path(dist_name)
        attributes = {'class': class_name, 'distName': dist_name,
                      'operation': operation, 'version': version}
        mo = ManagedObject().create(klass=class_name, dist_name=dist_name, version=version,
                                    operation=operation, ns=self._internal_scf.raml.xmlns)
        self._internal_scf.raml.cmData.append(mo)
        logging_message = 'Added managedObject with attributes: {}'.format(attributes)
        self._log_scf_modification(logging_message)

    def delete_block_from_scf_by_pattern(self, mo_name, element_name=None, p_name=None):
        """
        Remove MO, list, or single parameter in list from loaded SCF.

        KWs parameters are mapped to attributes of an SCF element. If ``p_name`` is given, it removes only a single
        element. If not, the whole managedObject is removed. Changes are saved only after ``save_scf`` keyword is
        executed.

        :param str mo_name: in <managedObject> 'distName' shall be used to provide last element after split operation
                            ('/' is used as separator) e.g.:
                            distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1

                            If there are more matches for the same mo_name e.g:
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0"
                            Then mo_name will be last two elements combined together -> mo_name = LNCEL-27251/SIB-0 etc.

        :param str element_name: 'name' of attribute in <list> or <p> tag, None is default value.
        :param str p_name: 'name' of attribute in <p> tag inside <list> tag, None is default value.
        """
        if element_name is None and p_name is None:
            self._get_node_by_mo(mo_name).remove()
        elif element_name is not None and p_name is None:
            self._get_node_by_mo(mo_name, element_name).remove()
        else:
            elem = self._get_elements_by_pattern(mo_name, element_name, p_name)
            for element in elem:
                element.remove()
        attributes = {'mo_name': mo_name, 'element_name': element_name,
                      'p_name': p_name}
        logging_message = 'Removed node with attributes: {}'
        self._log_scf_modification(logging_message.format(attributes))

    def _get_node_by_mo(self, mo_name=None, child_name=None):
        mos = self._internal_scf.raml.cmData.get_all_descendant_mos()
        for mo in mos:
            if mo.dist_name.endswith(mo_name):
                if not child_name:
                    return mo
                else:
                    node = getattr(mo, child_name)
                    return node

        raise ElementNotFound

    def modify_scf_list_with_list_of_values(self, mo_name, list_name, values_list):
        """ Modifies values in <p> tag of matched scf list. If match is found all elements
        under provided list are deleted and replaced with new ones specified by values_list
        parameter. Raises exception KeyError if less than one element found. Changes are saved
        only after usage of save_scf keyword.
        eg. values_list =[1,2,3]:

            <list name="wncelIdList">
                <p>3941</p>
                <p>3942</p>
                <p>3943</p>
            </list>

            will be changed to:

            <list name="wncelIdList">
                <p>1</p>
                <p>2</p>
                <p>3</p>
            </list>

        :param str mo_name: in <managedObject> 'distName' shall be used to provide last element after split operation
                            ('/' is used as separator) e.g.:
                            distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1

                            If there are more matches for the same mo_name e.g:
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0"
                            Then mo_name will be last two elements combined together -> mo_name = LNCEL-27251/SIB-0 etc.

        :param str list_name: 'name' attribute in <list> tag, None is default value.
        :param str values_list: string with comma separated 'values' which will be used as attributes in <p> tag.

        """
        values_list = values_list.split(',')
        values_list = list(filter(None, values_list))
        matched_elements = self._get_elements_by_pattern(mo_name=mo_name, list_name=list_name)
        for element in matched_elements:
            element.remove()
        parent = getattr(self._get_node_by_mo(mo_name), list_name)
        for value in values_list:
            elem = P().create(value=value, ns=self._internal_scf.raml.xmlns)
            parent.append(elem)
            logging_message = 'Added element "{}" to list "{}" in MO with name={}'
            logging_message = logging_message.format(element, list_name, mo_name)
            self._log_scf_modification(logging_message)

    def perform_operation_on_list_parameter(self, operation, mo_name, list_name, p_name=None, value=None,
                                            condition_key=None, condition_value=None):
        """
        This KW is responsible for list parameter modification.

        :param str operation: 'add', 'delete', 'modify' for operation to be made on single list parameter or
                              'delete_item' if whole list item should be deleted.
        :param str mo_name: in <managedObject> 'distName' shall be used to provide last element after split operation
                            ('/' is used as separator) e.g.:
                            distName="MRBTS-2725/TNLSVC-1/TNL-1/IPNO-1/RTPOL-1" -> mo_name = RTPOL-1

                            If there are more matches for the same mo_name e.g:
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27251/SIB-0"
                            distName="MRBTS-2725/LNBTS-2725/LNCEL-27252/SIB-0"
                            Then mo_name will be last two elements combined together -> mo_name = LNCEL-27251/SIB-0 etc.
        :param str list_name: 'name' of attribute in <list> tag, None is default value.
        :param str p_name: 'name' of attribute in <p> tag, None is default value
        :param str value: 'value' of attribute in <p> tag, None is default value
        :param str condition_key: 'name' of attribute in <p> tag in list item for which requested operation will be
                                   performed
        :param str condition_value: 'value' of condition_key attribute in <p> tag
        """

        elements = self._find_elements_to_process(mo_name=mo_name, list_name=list_name, condition_key=condition_key,
                                                  condition_value=condition_value)

        self._log_scf_modification(
            f"Perform {operation} {p_name} parameter on {list_name} list, inside {mo_name} with args: "
            f"value={value}, condition_key={condition_key}, condition_value={condition_value}")

        if not elements:
            self._log_scf_modification("No elements found for given parameters")

        for element in elements:
            if self._perform_operation_on_element(operation, element, mo_name, list_name, p_name, value):
                return

    def _perform_operation_on_element(self, operation, element, mo_name, list_name, p_name, value):
        if operation == 'delete_item':
            element.remove()
            return True
        if operation == 'add':
            if self._modify_if_param_exists(mo_name, list_name, p_name, element, value):
                return True
            p_elem = P().create(value=value, name=p_name, ns=self._internal_scf.raml.xmlns)
            element.append(p_elem)
            return True
        if operation in ['modify', 'delete']:
            is_parameter_changed = self._change_parameters(element, operation, p_name, value)
            if is_parameter_changed:
                return True

    def _modify_if_param_exists(self, mo_name, list_name, p_name, element, value):
        if self._get_all_elements(mo_name, list_name, p_name):
            logger.warning(f'[SCF MODIFICATION] Parameter "{p_name}" already exists, modifying its value to "{value}"!')
            return self._change_parameters(element, 'modify', p_name, value)

    def _change_parameters(self, element, operation, p_name, value):
        for parameter in element:
            if parameter.name == p_name:
                if operation == 'modify':
                    parameter.value = value
                    return True
                elif operation == 'delete':
                    parameter.remove()
                    return True
        return False

    def _find_elements_to_process(self, mo_name, list_name, condition_key, condition_value):
        matched_elements = self._get_node_by_mo(mo_name=mo_name, child_name=list_name)
        matched_elements = (el for el in matched_elements if not isinstance(el, P))
        for element in matched_elements:
            for parameter in element:
                if parameter.name == condition_key and str(parameter.value) == str(condition_value):
                    yield element
